// File: MathUtils.java
public class MathUtils {
    // Static utility method: no object state required
    public static double convertKmToMiles(double kilometers) {
        return kilometers * 0.621371;
    }

    public static boolean isDivisible(int number, int divisor) {
        if (divisor == 0) return false;
        return number % divisor == 0;
    }

    public static void main(String[] args) {
        // Direct call within the same class
        double miles = convertKmToMiles(10.0);
        System.out.println("10 km = " + miles + " miles");

        // Qualified call using ClassName.methodName()
        boolean test = MathUtils.isDivisible(15, 3);
        System.out.println("15 divisible by 3: " + test);
    }
}

