practice.solutionCode:
public class Main {
    public static double fahrenheitToCelsius(double f) {
        return (f - 32.0) * 5.0 / 9.0;
    }

    public static void main(String[] args) {
        double c = fahrenheitToCelsius(98.6);
        System.out.println("98.6 F = " + c + " C");
    }
}

