public class Main {
    public static boolean isInRange(int val, int min, int max) {
        return val >= min && val <= max;
    }

    public static void main(String[] args) {
        System.out.println("25 in [10, 50]: " + isInRange(25, 10, 50));
        System.out.println("75 in [10, 50]: " + isInRange(75, 10, 50));
    }
}

