practiceProblems.solutionCode:
public class Main {
    public static int absDifference(int a, int b) {
        if (a > b) {
            return a - b;
        }
        return b - a;
    }

    public static void main(String[] args) {
        System.out.println("Diff(12, 20): " + absDifference(12, 20));
        System.out.println("Diff(30, 15): " + absDifference(30, 15));
    }
}

