practiceProblems.solutionCode:
public class Main {
    public static boolean isPrime(int n) {
        if (n <= 1) return false;
        for (int i = 2; i * i <= n; i++) {
            if (n % i == 0) return false;
        }
        return true;
    }

    public static void main(String[] args) {
        System.out.println("7 Prime: " + isPrime(7));
        System.out.println("12 Prime: " + isPrime(12));
        System.out.println("29 Prime: " + isPrime(29));
    }
}

