public class Main {
    public static double usdToEur(double usd) {
        return usd * 0.92;
    }

    public static double usdToGbp(double usd) {
        return usd * 0.79;
    }

    public static void main(String[] args) {
        double amount = 200.0;
        System.out.println("200 USD = " + usdToEur(amount) + " EUR");
        System.out.println("200 USD = " + usdToGbp(amount) + " GBP");
    }
}
